function renderRoutes(){if(!$('#routeList'))return;const entries=visibleRouteEntries();$('#routeList').innerHTML=entries.length?entries.map(([i,r])=>`<button class="route-card ${i===selectedRouteIndex?'active':''}" data-route="${i}" title="Select, then drag this route to the map trash pin"><span class="route-icon">↕</span><span><strong>${escapeHtml(r.name)}</strong><small>${escapeHtml(r.direction)} · ${r.points.length} points · ${escapeHtml(formatFlightDate(r.date))}${r.label?` · ${escapeHtml(r.label)}`:''}${r.videoName?' · video linked':''}</small></span><span>⋯</span></button>`).join(''):'<div class="empty-flight-date">No saved flights for this date yet. Draw a route to add one.</div>';$$('.route-card').forEach(b=>{const index=+b.dataset.route;b.draggable=true;b.onclick=()=>selectRoute(index,true);b.addEventListener('dragstart',e=>{draggedRoute=savedRoutes[index];e.dataTransfer.setData('text/plain',String(index));e.dataTransfer.setData('application/x-skybuilt-route',String(index));e.dataTransfer.effectAllowed='move';selectedRouteIndex=index;$('#routeName').value=savedRoutes[index].name;$('#routeLabel').value=savedRoutes[index].label||'';$('#routeDirection').value=savedRoutes[index].direction;$('#flightDate').value=savedRoutes[index].date;$('#deleteRoute').disabled=false;b.classList.add('dragging')});b.addEventListener('dragend',()=>{draggedRoute=null;b.classList.remove('dragging');$('#routeTrashTarget').classList.remove('drag-over')})});$('#previewRoutes').textContent=entries.length;$('#deleteRoute').disabled=selectedRouteIndex===null||!entries.some(([i])=>i===selectedRouteIndex);$('#flightDateSummary').textContent=entries.length?`${entries.length} saved route${entries.length===1?'':'s'}${entries.some(([,r])=>r.videoName)?' · videos linked':''} for ${formatFlightDate(activeFlightDate)}.`:`No saved flights for ${formatFlightDate(activeFlightDate)} yet. New routes and videos will be added to this date.`}
