$('#routeVideoFile').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;const input=e.target,progress=$('#routeUploadProgress'),message=$('#routeUploadMessage'),status=$('#routeVideoStatus');input.disabled=true;progress.hidden=false;progress.setAttribute('aria-label',`Preparing ${file.name}`);message.textContent=`Preparing ${file.name}…`;status.textContent='';try{await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));const video={url:URL.createObjectURL(file),name:file.name,file};await new Promise(resolve=>setTimeout(resolve,320));if(selectedRouteIndex!==null&&savedRoutes[selectedRouteIndex]){const old=savedRoutes[selectedRouteIndex].videoUrl;if(old?.startsWith('blob:'))URL.revokeObjectURL(old);savedRoutes[selectedRouteIndex].videoUrl=video.url;savedRoutes[selectedRouteIndex].videoName=file.name;savedRoutes[selectedRouteIndex].videoFile=file;drawRoutes();status.textContent=`Linked: ${file.name}`}else{pendingRouteVideo=video;status.textContent=`Will link: ${file.name}`}message.textContent='Video ready';notice('Video linked to this route.')}catch(error){status.textContent='Could not prepare this video. Choose another file.';notice('Could not prepare this video.')}finally{input.disabled=false;setTimeout(()=>{progress.hidden=true},700)}});
