const addressInput=$('#addressInput'),suggestionBox=$('#addressSuggestions'),addressWrap=$('.address-input-wrap');
function addressParts(p){const road=[p.housenumber,p.street||(!p.housenumber?p.name:'')].filter(Boolean).join(' ').trim(),area=[p.postcode,p.city||p.district||p.county,p.state,p.country].filter((v,i,a)=>v&&a.indexOf(v)===i);return{title:road||p.name||p.city||'Address result',detail:area.join(', ')||p.country||'OpenStreetMap address',full:[road||p.name,area.join(', ')].filter(Boolean).join(', ')}}
function renderSuggestions(items,message){suggestionBox.replaceChildren();activeSuggestion=-1;if(message){const d=document.createElement('div');d.className='suggestion-status';d.textContent=message;suggestionBox.append(d);suggestionBox.hidden=false;return}items.forEach((f,i)=>{const p=f.properties||{},a=addressParts(p),b=document.createElement('button');b.type='button';b.className='address-suggestion';b.setAttribute('role','option');b.setAttribute('aria-selected','false');b.innerHTML=`<span class="suggestion-pin">⌖</span><span class="suggestion-copy"><strong>${escapeHtml(a.title)}</strong><small>${escapeHtml(a.detail)}</small></span>`;b.addEventListener('pointerdown',e=>e.preventDefault());b.addEventListener('click',()=>selectAddress(f));suggestionBox.append(b)});suggestionBox.hidden=!items.length;if(!items.length){const n=houseNumberFromQuery(addressInput.value);renderSuggestions([],n?`No exact match for #${n} yet. Add the city, state, or ZIP code.`:'No matching addresses. Try adding a city, state, or ZIP code.')}}
function updateSuggestionSelection(){[...suggestionBox.querySelectorAll('[role=option]')].forEach((el,i)=>{el.setAttribute('aria-selected',String(i===activeSuggestion));if(i===activeSuggestion)el.scrollIntoView({block:'nearest'})})}
function houseNumberFromQuery(query){return query.trim().match(/^(\d+[a-z]?(?:-\d+[a-z]?)?)\s+/i)?.[1]?.toLowerCase()||''}
function houseNumberFromFeature(feature){const p=feature.properties||{},raw=p.housenumber||p.name?.match(/^(\d+[a-z]?(?:-\d+[a-z]?)?)\s+/i)?.[1]||'';return String(raw).toLowerCase()}
function exactNumberMatches(features,query){const requested=houseNumberFromQuery(query);if(!requested)return features;return features.filter(f=>{const found=houseNumberFromFeature(f);return found===requested||found.startsWith(requested+'-')})}
function normalizeStreet(value){return String(value||'').toLowerCase().replace(/\b(st)\.?\b/g,'street').replace(/\b(rd)\.?\b/g,'road').replace(/\b(ave)\.?\b/g,'avenue').replace(/\b(blvd)\.?\b/g,'boulevard').replace(/\b(dr)\.?\b/g,'drive').replace(/\b(ln)\.?\b/g,'lane').replace(/\b(hwy)\.?\b/g,'highway').replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim()}
function featureText(f){const p=f.properties||{};return normalizeStreet([p.name,p.housenumber,p.street,p.postcode,p.city,p.district,p.county,p.state,p.country].filter(Boolean).join(' '))}
function proximityMeters(feature,center){const c=feature.geometry?.coordinates;if(!c||!center)return Infinity;const rad=v=>v*Math.PI/180,[lon,lat]=c,lat1=rad(lat),lat2=rad(center.lat),dLat=rad(center.lat-lat),dLon=rad(center.lng-lon),a=Math.sin(dLat/2)**2+Math.cos(lat1)*Math.cos(lat2)*Math.sin(dLon/2)**2;return 12742000*Math.asin(Math.sqrt(a))}
function addressMatches(features,query){let matches=exactNumberMatches(features,query);const first=query.split(',')[0].trim().replace(/^\d+[a-z]?(?:-\d+[a-z]?)?\s*/i,'').trim(),hasStreetType=/\b(st|street|rd|road|ave|avenue|blvd|boulevard|dr|drive|ln|lane|hwy|highway|way|court|ct|terrace|ter|place|pl|pike|parkway|pkwy)\b/i.test(first),street=normalizeStreet(first);if(street&&(houseNumberFromQuery(query)||hasStreetType))matches=matches.filter(f=>featureText(f).includes(street));const terms=normalizeStreet(query).split(' ').filter(t=>t.length>1&&!['the','of','and','usa','united','states'].includes(t)),center=map?.getCenter();return matches.map((feature,index)=>{const p=feature.properties||{},text=featureText(feature);let score=0;if(houseNumberFromQuery(query)===houseNumberFromFeature(feature))score+=1000;if(street&&text.includes(street))score+=220;for(const term of terms)if(text.includes(term))score+=18;if(p.city||p.state)score+=3;if(center)score-=Math.min(proximityMeters(feature,center)/500,100);return{feature,index,score}}).sort((a,b)=>b.score-a.score||a.index-b.index).slice(0,6).map(item=>item.feature)}
async function photonSearch(endpoint,params){const response=await fetch(`https://photon.komoot.io/${endpoint}?${params}`,{signal:suggestionAbort.signal,headers:{Accept:'application/json'}});if(!response.ok)throw Error('Address search is temporarily unavailable.');const data=await response.json();return data.features||[]}
