addressInput.addEventListener('input',()=>{const q=addressInput.value.trim();clearTimeout(suggestionTimer);if(suggestionAbort)suggestionAbort.abort();if(q.length<3){suggestionBox.hidden=true;return}renderSuggestions([],'Searching addresses…');suggestionTimer=setTimeout(async()=>{try{suggestions=await lookupAddresses(q);if(addressInput.value.trim()===q)renderSuggestions(suggestions)}catch(e){if(e.name!=='AbortError')renderSuggestions([], 'Could not reach address search. Check your connection and try again.')}},420)});
addressInput.addEventListener('keydown',e=>{const choices=suggestionBox.querySelectorAll('[role=option]');if(e.key==='ArrowDown'&&choices.length){e.preventDefault();activeSuggestion=Math.min(activeSuggestion+1,choices.length-1);updateSuggestionSelection()}else if(e.key==='ArrowUp'&&choices.length){e.preventDefault();activeSuggestion=Math.max(activeSuggestion-1,0);updateSuggestionSelection()}else if(e.key==='Escape'){suggestionBox.hidden=true}else if(e.key==='Enter'){e.preventDefault();if(activeSuggestion>=0&&suggestions[activeSuggestion])selectAddress(suggestions[activeSuggestion]);else findSite()}});
