function addSiteMarker(label){if(!map)return;if(mapProvider==='google'){if(window.siteGoogleMarker)window.siteGoogleMarker.setMap(null);window.siteGoogleMarker=new google.maps.Marker({map,position:{lat:siteCenter[0],lng:siteCenter[1]},title:`Project center · ${label} · drag to adjust`,label:'⌖',draggable:!boundaryLocked});window.siteGoogleMarker.addListener('dragend',e=>{siteCenter=[e.latLng.lat(),e.latLng.lng()];siteZoom=map.getZoom();map.setCenter({lat:siteCenter[0],lng:siteCenter[1]});notice('Center point moved. Return to site will navigate here.')});return}siteMarkerLayer.clearLayers();const icon=L.divIcon({className:'direction-marker address-marker',html:'<span>⌖</span>',iconSize:[36,40],iconAnchor:[18,34]});window.siteLeafletCenterMarker=L.marker(siteCenter,{icon,draggable:!boundaryLocked,title:'Project center · drag to adjust'}).addTo(siteMarkerLayer).bindPopup(`<strong>Project center</strong><br>${escapeHtml(label)}<br>Drag to adjust`);window.siteLeafletCenterMarker.on('dragend',e=>{const p=e.target.getLatLng();siteCenter=[p.lat,p.lng];siteZoom=map.getZoom();map.setView(siteCenter,siteZoom);notice('Center point moved. Return to site will navigate here.')})}
function selectAddress(feature){const p=feature.properties||{},coords=feature.geometry?.coordinates;if(!coords||coords.length<2)return;const [lon,lat]=coords;siteCenter=[lat,lon];const formatted=addressParts(p);addressInput.value=formatted.full||formatted.title;suggestionBox.hidden=true;savedRoutes=[];draftPath=[];$('#pathPointCount').textContent='0';drawRoutes();if(map){const zoom=p.housenumber?18:p.street?17:(p.osm_value==='city'||p.osm_value==='town'?14:16);siteZoom=zoom;if(mapProvider==='google'){if(boundaryLocked)map.setOptions({restriction:null});map.setCenter({lat,lng:lon});map.setZoom(zoom);siteBounds=null;google.maps.event.addListenerOnce(map,'idle',()=>{siteBounds=expandedGoogleBounds(map.getBounds()?.toJSON(),.22);lockMap(true)});addSiteMarker(formatted.full||formatted.title)}else{if(boundaryLocked)map.setMaxBounds(null);if(p.extent&&p.housenumber!==undefined){const [west,north,east,south]=p.extent;map.fitBounds([[south,west],[north,east]],{maxZoom:18,padding:[28,28]})}else map.setView(siteCenter,zoom);map.once('moveend',()=>{const b=map.getBounds();siteBounds=L.latLngBounds(b.getSouthWest(),b.getNorthEast()).pad(.22);lockMap(true)});selectedAddressMarker(feature,formatted.full||formatted.title)}}notice('Map centered on the selected address and locked to this view.')}
