async function findSite(){const q=addressInput.value.trim();if(!q)return;$('#searchAddress').textContent='Finding…';try{const features=await lookupAddresses(q);if(!features.length){const n=houseNumberFromQuery(q);renderSuggestions([],n?`No exact match for #${n}. Check the street number or add the ZIP code.`:'No matching addresses. Add a city, state, or ZIP code.');return}suggestions=features;if(features.length>1){renderSuggestions(features);return}selectAddress(features[0])}catch(e){if(e.name!=='AbortError')notice(e.message==='Failed to fetch'?'Address search needs an internet connection.':e.message)}finally{$('#searchAddress').textContent='Set location'}}$('#searchAddress').onclick=findSite;$('#layerButton').onclick=()=>{if(!map)return;satellite=!satellite;if(mapProvider==='google'){map.setMapTypeId(satellite?'satellite':'roadmap');$('#layerButton').innerHTML=satellite?'▧ <span>Map</span>':'▧ <span>Satellite</span>';return}if(satellite){map.removeLayer(streetLayer);satelliteLayer.addTo(map);$('#layerButton').innerHTML='▧ <span>Map</span>'}else{map.removeLayer(satelliteLayer);streetLayer.addTo(map);$('#layerButton').innerHTML='▧ <span>Satellite</span>'}};

