function saveCurrentMapLayout(name){if(!map||!name?.trim())return;const c=map.getCenter(),b=map.getBounds(),center=mapProvider==='google'?[c.lat(),c.lng()]:[c.lat,c.lng],bounds=mapProvider==='google'?b?.toJSON():{north:b.getNorth(),south:b.getSouth(),east:b.getEast(),west:b.getWest()};const layout={name:name.trim(),center,zoom:map.getZoom(),bounds,satellite,routes:savedRoutes.filter(r=>r.date===$('#flightDate').value).map(r=>({name:r.name,label:r.label||'',direction:r.direction,points:r.points.map(p=>[...p]),color:r.color}))};savedMapLayouts.push(layout);localStorage.setItem('site-capture-map-layouts',JSON.stringify(savedMapLayouts));renderSavedMapLayouts();$('#savedMapLayouts').value=String(savedMapLayouts.length-1);$('#applyMapLayout').disabled=false;$('#saveLayoutModal').hidden=true;notice(`“${layout.name}” saved for future flights.`)}
