function openSaveProjectDialog(){
  if(draftPath.length===1){notice('Add another point or clear the unfinished route before saving.');return}
  if(pendingRouteVideo&&draftPath.length<2){notice('Draw and save a route before attaching its video.');return}
  if(draftPath.length>=2&&!saveCurrentRoute())return;
  const modal=$('#saveProjectModal'),form=$('#saveProjectForm');
  $('#saveProjectError').hidden=true;$('#saveProjectError').textContent='';
  $('#saveProjectName').value=$('#saveProjectName').value.trim()||'Harrisburg Commerce Center';
  modal.hidden=false;$('#saveProjectName').focus();
}
$('#saveProjectButton').onclick=openSaveProjectDialog;
$('#cancelSaveProject').onclick=$('#cancelSaveProject2').onclick=()=>$('#saveProjectModal').hidden=true;
$('#saveProjectModal').addEventListener('click',e=>{if(e.target===$('#saveProjectModal'))$('#saveProjectModal').hidden=true});
$('#saveProjectForm').addEventListener('submit',async e=>{
  e.preventDefault();const form=e.currentTarget,button=$('#confirmSaveProject'),error=$('#saveProjectError');
  const center=mapProvider==='google'?[map.getCenter().lat(),map.getCenter().lng()]:[map.getCenter().lat,map.getCenter().lng];
  const payload={project_name:$('#saveProjectName').value.trim(),module:activeModule,address:addressInput.value.trim(),center,zoom:map.getZoom(),routes:savedRoutes.map(r=>({name:r.name,label:r.label||'',direction:r.direction,date:r.date||activeFlightDate,points:r.points})),annotations:activeView==='photos'?{areas:photoState.areas.map(a=>({name:a.name,points:a.points})),pins:photoState.pins.map(p=>({x:p.x,y:p.y,label:p.label}))}:{areas:[],pins:[]}};
  const body=new FormData();body.append('project_data',JSON.stringify(payload));
  if(pendingSiteReferenceFile)body.append('site_reference',pendingSiteReferenceFile,pendingSiteReferenceFile.name);
  savedRoutes.forEach((r,i)=>{if(r.videoFile)body.append(`route_video_${i}`,r.videoFile,r.videoFile.name)});
  button.disabled=true;button.textContent='Saving project…';error.hidden=true;error.textContent='';
  try{const response=await fetch(form.dataset.url,{method:'POST',body,credentials:'same-origin',headers:{'X-CSRF-Token':form.dataset.csrf}});const result=await response.json();if(!response.ok)throw new Error(result.error||'Could not save the project.');button.textContent='Opening viewer…';window.location.assign(result.viewer_url)}
  catch(err){error.textContent=err.message||'Could not save the project. Keep the editor open and try again.';error.hidden=false;button.disabled=false;button.textContent='Save and open viewer'}
});
